css:
@page {
	size: A4 portrait;
	margin: 8mm 10mm 10mm 10mm;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
}

.print-format * {
	-webkit-print-color-adjust: exact !important;
	print-color-adjust: exact !important;
}

.print-format th {
	text-transform: none !important;
}

.print-heading h2,
.print-format > .letter-head {
	display: none !important;
}

.nyc-form {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 10.5pt;
	color: #111;
	width: 100%;
}

.nyc-letterhead {
	width: 100%;
	text-align: center;
	margin: 0 0 6px 0;
}

.nyc-letterhead img {
	width: 100% !important;
	max-width: 100% !important;
	height: auto !important;
	display: block;
	margin: 0 auto;
}

.nyc-docbar {
	width: 100%;
	border-collapse: collapse;
	margin: 2px 0 8px 0;
	table-layout: fixed;
}

.nyc-docbar td {
	border: none;
	border-bottom: 2px solid #1a3d7c;
	padding: 2px 0 6px 0;
	font-size: 8.5pt;
	font-weight: 700;
	color: #1a3d7c;
}

.nyc-docbar td:nth-child(1) { text-align: left; }
.nyc-docbar td:nth-child(2) { text-align: center; }
.nyc-docbar td:nth-child(3) { text-align: right; }

.nyc-title {
	text-align: center;
	font-size: 14pt;
	font-weight: 800;
	margin: 10px 0 12px;
	text-transform: uppercase;
	color: #111;
	letter-spacing: 0.2px;
}

.nyc-box {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 12px;
	table-layout: fixed;
}

.nyc-box td {
	border: 1px solid #222;
	padding: 7px 8px;
	vertical-align: middle;
}

.nyc-box .lbl {
	width: 34%;
	font-weight: 700;
	background: #f3f3f3;
}

.nyc-section-title {
	margin: 10px 0 4px;
	font-weight: 700;
	font-size: 11pt;
}

.nyc-details-box {
	border: 1px solid #222;
	min-height: 56px;
	padding: 8px 10px;
	margin-bottom: 12px;
}

.nyc-details-box p {
	margin: 0 0 4px 0;
}

.nyc-reassessment-head {
	width: 100%;
	border-collapse: collapse;
	margin: 4px 0 4px;
}

.nyc-reassessment-head td {
	border: none;
	padding: 0 0 4px 0;
	vertical-align: bottom;
}

.nyc-date-time {
	text-align: right;
	font-size: 10pt;
}

.nyc-grid {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 12px;
	table-layout: fixed;
}

.nyc-grid th,
.nyc-grid td {
	border: 1px solid #222;
	padding: 6px 6px;
	vertical-align: middle;
}

.nyc-grid th {
	background: #1a3d7c;
	color: #fff;
	font-weight: 700;
	text-align: center;
	font-size: 9.5pt;
}

.nyc-grid td {
	height: 26px;
}

.col-ref { width: 7%; text-align: center; }
.col-outcome { width: 38%; }
.col-done { width: 12%; text-align: center; font-weight: 700; }
.col-source { width: 25%; }
.col-remarks { width: 18%; }

.nyc-declaration {
	margin: 10px 0 12px;
	line-height: 1.45;
	font-size: 10pt;
}

.nyc-sign {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin-top: 4px;
	page-break-inside: avoid;
}

.nyc-sign td {
	border: 1px solid #222;
	padding: 8px 10px;
	vertical-align: top;
	height: 78px;
	width: 33.33%;
}

.nyc-sign-label {
	font-size: 8.5pt;
	font-weight: 700;
	color: #1a3d7c;
	margin-bottom: 8px;
	text-transform: uppercase;
}

.nyc-sign-value {
	font-size: 11pt;
	min-height: 28px;
}

.nyc-sign-img {
	max-height: 48px;
	max-width: 150px;
	display: block;
}

.nyc-acc-footer {
	width: 100%;
	margin-top: 14px;
}

.nyc-acc-footer img {
	width: 100% !important;
	height: auto !important;
	display: block;
}

.nyc-pagefoot {
	width: 100%;
	border-collapse: collapse;
	margin-top: 4px;
}

.nyc-pagefoot td {
	border: none;
	border-top: 1px solid #1a3d7c;
	padding: 5px 0 0 0;
	font-size: 8pt;
	color: #444;
}

.nyc-pagefoot .right {
	text-align: right;
}
